import Link from "next/link";
import type { Metadata } from "next";
export const metadata: Metadata = { title: "Preguntas frecuentes", description: "Respuestas sobre compras, pagos, envíos y devoluciones.", alternates: { canonical: "/preguntas-frecuentes" } };
const entries = [["¿Cómo compro?", "Elegí productos, revisá el carrito y seguí el checkout."], ["¿Qué medios de pago hay?", "Los medios disponibles se muestran antes de confirmar la compra."], ["¿Cómo sigo mi pedido?", "Cuando exista seguimiento, estará disponible en el estado de la orden."], ["¿Cuánto demora el envío?", "Los plazos son estimados y pueden variar por proveedor, aduana y transportista."], ["¿Los productos pueden ser internacionales?", "Sí, el origen puede ser internacional."], ["¿Qué hago ante un problema de pago?", "No repitas pagos; contactanos con el número de orden."], ["¿Cambios o devoluciones?", "Consultá nuestra política antes de iniciar una solicitud."], ["¿Necesito cuenta?", "Podés gestionar tu cuenta y órdenes desde la tienda."], ["¿Cómo contacto soporte?", "Usá los canales publicados en contacto."]];
export default function FaqNewPage() { return <main className="mx-auto max-w-4xl px-4 py-16"><h1 className="text-3xl font-semibold">Preguntas frecuentes</h1><div className="mt-8 space-y-4">{entries.map(([question, answer]) => <section key={question}><h2 className="font-semibold">{question}</h2><p className="mt-1 text-neutral-600">{answer}</p></section>)}</div><p className="mt-8"><Link className="underline" href="/envios">Envíos</Link> · <Link className="underline" href="/cambios-y-devoluciones">Devoluciones</Link> · <Link className="underline" href="/contacto">Contacto</Link></p></main>; }
